// Speed vs. accuracy plot (paper Fig. speed_acc, generated by eval/paper_speed_acc.py).
// x = total runtime per image (network + camera-model fit, ms), y = mAA of the angular error at 5 deg (%), mean over the ten benchmarks.
// The Jetson panel keeps the A100 accuracy (same networks as fp16 engines).

const METHODS = [
	{ key: "geocalib", name: "GeoCalib", color: "#7F7F7F", shape: "square" },
	{ key: "unik3d", name: "UniK3D", color: "#BCBD22", shape: "triangle" },
	{ key: "acgen", name: "AnyCalib (released)", color: "#8C564B", shape: "diamond" },
	{ key: "acours", name: "AnyCalib (our data)", color: "#E377C2", shape: "diamond", line: true },
	{ key: "ours", name: "LiteCalib", color: "#1a73b3", shape: "circle", line: true },
];

const DEVICES = {
	jetson: {
		xLabel: "Total runtime on Jetson Orin Nano (ms)",
		xDomain: [8, 2500],
		xTicks: [10, 20, 50, 100, 200, 500, 1000, 2000],
		points: {
			geocalib: [[1466.5, 47.4]],
			unik3d: [[443.28, 50.5]],
			acgen: [[400.5, 58.5]],
			acours: [[31.5, 60.94, "ViT-S"], [100.6, 73.86, "ViT-L"]],
			ours: [[12.3, 62.21, "ViT-S"], [27.1, 66.6, "ViT-B"], [79.3, 73.68, "ViT-L"]],
		},
		arrow: { from: 31.5, to: 12.3, y: 56, text: "2.6× faster", below: true },
		note: "Jetson Orin Nano 8 GB, 15 W, TensorRT fp16. Runtime includes the camera-model fit; accuracy as on the A100.",
	},
	a100: {
		xLabel: "Total runtime on A100 (ms)",
		xDomain: [4.4, 130],
		xTicks: [5, 10, 20, 50, 100],
		points: {
			geocalib: [[102.8, 47.4]],
			unik3d: [[41.51, 50.5]],
			acgen: [[52.7, 58.5]],
			acours: [[9.36, 60.94, "ViT-S"], [15.05, 73.86, "ViT-L"]],
			ours: [[6.31, 62.21, "ViT-S"], [6.61, 66.6, "ViT-B"], [10.47, 73.68, "ViT-L"]],
		},
		arrow: { from: 15.05, to: 10.47, y: 77.3, text: "1.4×", below: false },
		note: "A100, fp16, batch 1. Runtime includes the camera-model fit; mAA@5° averaged over ten benchmarks.",
	},
};

const Y_DOMAIN = [45, 80];
const Y_TICKS = [45, 50, 55, 60, 65, 70, 75, 80];
const NS = "http://www.w3.org/2000/svg";

function el(name, attrs = {}, parent) {
	const node = document.createElementNS(NS, name);
	for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
	if (parent) parent.appendChild(node);
	return node;
}

function markPath(shape, x, y, r) {
	switch (shape) {
		case "square": return `M${x - r * 0.85},${y - r * 0.85}h${r * 1.7}v${r * 1.7}h${-r * 1.7}z`;
		case "triangle": return `M${x},${y - r * 1.15}L${x + r},${y + r * 0.7}L${x - r},${y + r * 0.7}z`;
		case "diamond": return `M${x},${y - r * 1.2}L${x + r},${y}L${x},${y + r * 1.2}L${x - r},${y}z`;
		default: return `M${x - r},${y}a${r},${r} 0 1,0 ${2 * r},0a${r},${r} 0 1,0 ${-2 * r},0`;
	}
}

function render(container, device) {
	const cfg = DEVICES[device];
	const W = Math.max(280, container.clientWidth);
	const H = Math.round(W < 560 ? W * 0.85 : Math.min(420, W * 0.5));
	const m = { l: 48, r: 16, t: 14, b: 46 };
	const iw = W - m.l - m.r, ih = H - m.t - m.b;

	const [x0, x1] = cfg.xDomain.map(Math.log10);
	const sx = (v) => m.l + ((Math.log10(v) - x0) / (x1 - x0)) * iw;
	const sy = (v) => m.t + (1 - (v - Y_DOMAIN[0]) / (Y_DOMAIN[1] - Y_DOMAIN[0])) * ih;

	const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, role: "img",
		"aria-label": `Accuracy against total runtime on ${device === "a100" ? "A100" : "Jetson Orin Nano"}` });

	// grid + axes
	const grid = el("g", { class: "grid" }, svg);
	const axis = el("g", { class: "axis" }, svg);
	for (const t of Y_TICKS) {
		el("line", { x1: m.l, x2: m.l + iw, y1: sy(t), y2: sy(t) }, grid);
		const tick = el("g", { class: "tick" }, axis);
		el("text", { x: m.l - 8, y: sy(t), "text-anchor": "end", "dominant-baseline": "middle" }, tick).textContent = t;
	}
	let lastTick = -Infinity;
	for (const t of cfg.xTicks) {
		if (sx(t) - lastTick < 34) continue;  // thin out the ticks on narrow screens
		lastTick = sx(t);
		el("line", { x1: sx(t), x2: sx(t), y1: m.t, y2: m.t + ih }, grid);
		const tick = el("g", { class: "tick" }, axis);
		el("text", { x: sx(t), y: m.t + ih + 16, "text-anchor": "middle" }, tick).textContent = t;
	}
	el("path", { d: `M${m.l},${m.t}V${m.t + ih}H${m.l + iw}`, fill: "none" }, axis);
	el("text", { class: "axis-label", x: m.l + iw / 2, y: H - 6, "text-anchor": "middle" }, svg).textContent = cfg.xLabel;
	el("text", { class: "axis-label", transform: `translate(13,${m.t + ih / 2}) rotate(-90)`, "text-anchor": "middle" }, svg)
		.textContent = "mAA at 5° (%)";

	// speed-up arrow
	const a = cfg.arrow;
	const defs = el("defs", {}, svg);
	const marker = el("marker", { id: "lcArrow", viewBox: "0 0 10 10", refX: 9, refY: 5, markerWidth: 7, markerHeight: 7, orient: "auto" }, defs);
	el("path", { d: "M0,0L10,5L0,10z", fill: "#94a3b8" }, marker);
	el("line", { x1: sx(a.from) - 6, x2: sx(a.to) + 6, y1: sy(a.y), y2: sy(a.y), stroke: "#94a3b8", "stroke-width": 1.5, "marker-end": "url(#lcArrow)" }, svg);
	el("text", { class: "annot", x: (sx(a.from) + sx(a.to)) / 2, y: sy(a.y) + (a.below ? 16 : -7), "text-anchor": "middle" }, svg).textContent = a.text;

	// series
	for (const meth of METHODS) {
		const pts = cfg.points[meth.key];
		const g = el("g", {}, svg);
		if (meth.line) {
			el("polyline", { points: pts.map(([x, y]) => `${sx(x)},${sy(y)}`).join(" "), fill: "none", stroke: meth.color, "stroke-width": 2.5 }, g);
		}
		for (const [x, y, label] of pts) {
			const p = el("path", { class: "mark", d: markPath(meth.shape, sx(x), sy(y), meth.key === "ours" ? 6 : 6.5), fill: meth.color }, g);
			el("title", {}, p).textContent = `${meth.name}${label ? " " + label : ""}: ${x < 20 ? x.toFixed(1) : Math.round(x)} ms, mAA ${y.toFixed(1)} %`;
			if (label) {
				// AnyCalib's labels to the right; ours: ViT-S below, ViT-B left, ViT-L above (as in the paper's figure)
				const pos = meth.key === "acours" ? "right" : { "ViT-S": "bottom", "ViT-B": "left", "ViT-L": "top" }[label];
				const at = {
					right: { x: sx(x) + 10, y: sy(y) + 4, "text-anchor": "start" },
					left: { x: sx(x) - 10, y: sy(y) + 4, "text-anchor": "end" },
					top: { x: sx(x), y: sy(y) - 11, "text-anchor": "middle" },
					bottom: { x: sx(x), y: sy(y) + 19, "text-anchor": "middle" },
				}[pos];
				el("text", { class: "pt-label", ...at }, g).textContent = label;
			}
		}
	}

	container.replaceChildren(svg);
}

function renderLegend(node) {
	node.replaceChildren(...[...METHODS].reverse().map((meth) => {
		const span = document.createElement("span");
		const svg = el("svg", { width: 14, height: 14, viewBox: "0 0 14 14" });
		el("path", { d: markPath(meth.shape, 7, 7, 5), fill: meth.color }, svg);
		span.append(svg, meth.name);
		return span;
	}));
}

export function initSpeedAccuracy() {
	const chart = document.getElementById("speedAccChart");
	const note = document.getElementById("speedAccNote");
	if (!chart) return;
	renderLegend(document.getElementById("speedAccLegend"));

	let device = "jetson";
	const buttons = document.querySelectorAll(".lc-toggle [data-device]");
	const draw = () => {
		render(chart, device);
		note.textContent = DEVICES[device].note;
		buttons.forEach((b) => {
			b.classList.toggle("is-selected", b.dataset.device === device);
			b.setAttribute("aria-pressed", b.dataset.device === device);
		});
	};
	buttons.forEach((b) => b.addEventListener("click", () => { device = b.dataset.device; draw(); }));

	let frame;
	new ResizeObserver(() => { cancelAnimationFrame(frame); frame = requestAnimationFrame(draw); }).observe(chart);
	draw();
}